import { bigint, customType, foreignKey, index, jsonb, pgTable, text, timestamp, unique, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import type { AcmeEnvironment } from "../certificate-authority";
import type { DnsProviderType } from "../dns-provider-kinds";
import type { IssuanceFailureCode } from "../issuance-failure";
import type { KeyAlgorithm, KeyCustody } from "../csr";
import { organization } from "./auth-schema";

// Better Auth's tables (generated by `bun run auth:generate`; do not edit by hand).
export * from "./auth-schema";

const bytea = customType<{ data: Buffer }>({ dataType: () => "bytea" });

/** Every domain table carries organization_id and every query filters by it. */
export const managedCertificate = pgTable(
  "managed_certificate",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    /** The names to issue, lower case, wildcards as `*.example.com`; in the order the creator gave them. */
    names: text("names").array().notNull(),
    keyAlgorithm: text("key_algorithm").$type<KeyAlgorithm>().notNull(),
    keyCustody: text("key_custody").$type<KeyCustody>().notNull(),
    /** Which of the Organization's ACME accounts, by environment, Certificates are obtained through. */
    environment: text("environment").$type<AcmeEnvironment>().notNull(),
    /** The CSR under which Certificates are issued (Key Custody: Owner), so Renewal can reuse it. */
    csr: text("csr").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("managed_certificate_org_idx").on(t.organizationId),
    // Lets other tables reference a Managed Certificate together with its Organization, so none can point at another's.
    unique("managed_certificate_id_organization_unique").on(t.id, t.organizationId),
  ],
);

/**
 * Append-only audit log, one row per state change, written in the same transaction as the change
 * it records. A trigger (see the audit_event_append_only migration) rejects UPDATE and DELETE.
 */
export const auditEvent = pgTable(
  "audit_event",
  {
    id: bigint("id", { mode: "number" }).primaryKey().generatedAlwaysAsIdentity(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull(),
    actorId: text("actor_id"),
    actorEmail: text("actor_email"),
    action: text("action").notNull(),
    targetType: text("target_type").notNull(),
    targetId: text("target_id"),
    detail: jsonb("detail").$type<Record<string, unknown>>().notNull().default({}),
  },
  (t) => [index("audit_event_org_idx").on(t.organizationId, t.id)],
);

/** An Organization's data key, wrapped by the KMS. The unwrapped key is never stored. */
export const organizationDataKey = pgTable("organization_data_key", {
  organizationId: text("organization_id")
    .primaryKey()
    .references(() => organization.id),
  wrappedKey: bytea("wrapped_key").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/** A write-only value (an ACME account key, later DNS Provider credentials), encrypted under its Organization's data key. */
export const secret = pgTable(
  "secret",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    ciphertext: bytea("ciphertext").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  // Lets other tables reference a secret together with its Organization, so none can point at another's.
  (t) => [unique("secret_id_organization_unique").on(t.id, t.organizationId)],
);

/** An Organization's account with a CA, in one of its environments. Its key is a secret and is never returned. */
export const acmeAccount = pgTable(
  "acme_account",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    environment: text("environment").$type<AcmeEnvironment>().notNull(),
    accountUrl: text("account_url").notNull(),
    contactEmail: text("contact_email"),
    secretId: uuid("secret_id").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("acme_account_organization_environment_unique").on(t.organizationId, t.environment),
    foreignKey({ columns: [t.secretId, t.organizationId], foreignColumns: [secret.id, secret.organizationId] }),
  ],
);

/** An Organization's connection to a DNS service. Its settings are shown to administrators; its secret never is. */
export const dnsProvider = pgTable(
  "dns_provider",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    name: text("name").notNull(),
    type: text("type").$type<DnsProviderType>().notNull(),
    settings: jsonb("settings").$type<Record<string, unknown>>().notNull(),
    secretId: uuid("secret_id").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("dns_provider_organization_name_unique").on(t.organizationId, t.name),
    foreignKey({ columns: [t.secretId, t.organizationId], foreignColumns: [secret.id, secret.organizationId] }),
  ],
);

/**
 * One attempt to obtain a Certificate for a Managed Certificate: it runs while the platform does DCV and finalizes the
 * order, and ends in a Certificate or in the cause of its failure. At most one runs at a time for a Managed Certificate.
 */
export const issuance = pgTable(
  "issuance",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    managedCertificateId: uuid("managed_certificate_id").notNull(),
    status: text("status").$type<"running" | "succeeded" | "failed">().notNull(),
    /** Who asked for it; the Audit Events of its outcome are attributed to them. */
    requestedById: text("requested_by_id").notNull(),
    requestedByEmail: text("requested_by_email").notNull(),
    failureCode: text("failure_code").$type<IssuanceFailureCode>(),
    failureMessage: text("failure_message"),
    certificateId: uuid("certificate_id"),
    startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({ columns: [t.managedCertificateId, t.organizationId], foreignColumns: [managedCertificate.id, managedCertificate.organizationId] }),
    index("issuance_managed_certificate_idx").on(t.managedCertificateId, t.createdAt),
    uniqueIndex("issuance_one_running_per_managed_certificate")
      .on(t.managedCertificateId)
      .where(sql`${t.status} = 'running'`),
  ],
);

/**
 * One issued X.509 certificate, identified by its fingerprint. Immutable: a trigger (see the
 * certificate_immutable migration) rejects UPDATE and DELETE.
 */
export const certificate = pgTable(
  "certificate",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id),
    managedCertificateId: uuid("managed_certificate_id").notNull(),
    /** SHA-256 of the leaf's DER, lower-case hex. */
    fingerprint: text("fingerprint").notNull(),
    /** The leaf's serial number, upper-case hex. */
    serial: text("serial").notNull(),
    notBefore: timestamp("not_before", { withTimezone: true }).notNull(),
    notAfter: timestamp("not_after", { withTimezone: true }).notNull(),
    /** The names the leaf covers (its subject alternative names), lower case. */
    names: text("names").array().notNull(),
    /** The leaf followed by the intermediates the CA served, PEM. */
    chainPem: text("chain_pem").notNull(),
    /** The CA it came from (its name in the Certificate Authority interface), and the ACME account used there. */
    ca: text("ca").notNull(),
    environment: text("environment").$type<AcmeEnvironment>().notNull(),
    acmeAccountId: uuid("acme_account_id")
      .notNull()
      .references(() => acmeAccount.id),
    issuedAt: timestamp("issued_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    unique("certificate_organization_fingerprint_unique").on(t.organizationId, t.fingerprint),
    index("certificate_managed_certificate_idx").on(t.managedCertificateId, t.createdAt),
    foreignKey({ columns: [t.managedCertificateId, t.organizationId], foreignColumns: [managedCertificate.id, managedCertificate.organizationId] }),
  ],
);
